import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams, useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const ListaCurso = () => {
  const { id } = useParams(); // Obtém o ID do professor da URL
  const navigate = useNavigate();
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);

  // Função para buscar os cursos do professor
  const fetchCursosProfessor = async () => {
    try {
      const resposta = await private_api.get(`/professores/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      }
    } catch (error) {
      console.error("Erro ao buscar cursos do professor:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCursosProfessor();
  }, [id]);

  if (loading) {
    return (
      <div
        className="container-fluid d-flex flex-column align-items-center justify-content-center"
        style={{ backgroundColor: "#E7EFF4", minHeight: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <div className="bg-white w-75 p-2 d-flex justify-content-center">
        <nav className="nav nav-tabs">
          <a className="nav-link active mx-3" href="#">
            Cursos
          </a>
          <a
            className="nav-link mx-3"
            href="#"
            onClick={() => navigate(`/professoraulas/${id}`)}
          >
            Aulas
          </a>
          <a
            className="nav-link mx-3"
            href="#"
            onClick={() => navigate(`/professoravaliacoes/${id}`)}
          >
            Avaliações
          </a>
        </nav>
      </div>

      <h2 className="mb-3 text-left w-75">Lista de Cursos</h2>
      <table className="table table-bordered bg-white w-75">
        <thead>
          <tr>
            <th>Curso</th>
            <th>Nível</th>
            <th>Data de Início</th>
            <th>Data de Fim</th>
            <th>Período</th>
            <th>Estado</th>
          </tr>
        </thead>
        <tbody>
          {cursos.length > 0 ? (
            cursos.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>{new Date(curso.dataInicio).toLocaleDateString()}</td>
                <td>{new Date(curso.dataFim).toLocaleDateString()}</td>
                <td>{curso.periodo === "manha" ? "Manhã" : "Tarde"}</td>
                <td>
                  {new Date(curso.dataFim) > new Date()
                    ? "Em andamento"
                    : "Concluído"}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="6" className="text-center">
                Nenhum curso encontrado para este professor
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <h3 className="mt-4 w-75">Inscrições</h3>
      <div className="card p-3 w-75">
        <div className="d-flex justify-content-between align-items-center">
          <span>Inscrever-se em um Curso</span>
          <button className="btn btn-link">Ver Detalhes</button>
        </div>
      </div>
    </div>
  );
};

export default ListaCurso;
